import { afterEach, expect, test, vi } from "vitest";
import { build } from "../test-utils/build-app";
import { generateMockLicense } from "../test-utils/mock-license";

const URL = "/api/v1/instance-reports";

const report = {
  instanceId: "instance-1",
  batchId: "batch-1",
  n8nVersion: "1.99.0",
  dataPoints: [{ kind: "cumulative", name: "activeWorkflows", value: 1 }],
  licenseCert: generateMockLicense(),
};

// The plugin reads both variables when it registers, so each test stubs them
// before build(). unstubAllEnvs restores whatever was set before the stub,
// so the file does not depend on when build-app.ts assigns the cert.
afterEach(() => {
  vi.unstubAllEnvs();
});

test("trusts the test CA under NODE_ENV=test", async () => {
  const app = await build();

  const res = await app.inject({ method: "POST", url: URL, payload: report });
  expect(res.statusCode).toBe(201);
});

// The production image bakes NODE_ENV=production. Setting the variable on a
// deployed container must change nothing.
test("ignores TEST_LICENSE_ISSUER_CERT outside NODE_ENV=test", async () => {
  vi.stubEnv("NODE_ENV", "production");
  const app = await build();

  const res = await app.inject({ method: "POST", url: URL, payload: report });
  expect(res.statusCode).toBe(401);
});

// A test run that lost the variable must not quietly fall back to accepting
// only real certificates while mock ones fail: the fixture is the mock CA.
test("uses the embedded n8n CA when TEST_LICENSE_ISSUER_CERT is unset", async () => {
  vi.stubEnv("TEST_LICENSE_ISSUER_CERT", undefined);
  const app = await build();

  const res = await app.inject({ method: "POST", url: URL, payload: report });
  expect(res.statusCode).toBe(401);
});

// Certificate mode is the default, and in it a bearer header is not a
// credential at all: it is neither checked nor a substitute for the
// certificate.
test("ignores bearer headers in certificate mode", async () => {
  const app = await build();
  expect(app.config.writeToken).toBeUndefined();

  const { licenseCert: _omitted, ...bare } = report;
  const headers = { authorization: "Bearer anything" };

  const withoutCert = await app.inject({ method: "POST", url: URL, headers, payload: bare });
  expect(withoutCert.statusCode).toBe(401);
  expect(withoutCert.json()).toMatchObject({ message: "Missing license certificate" });

  const withCert = await app.inject({ method: "POST", url: URL, headers, payload: report });
  expect(withCert.statusCode).toBe(201);
});

// A blank value is the same as unset, so a templated `WRITE_TOKEN=` line in a
// deployment leaves the service in certificate mode rather than turning the
// empty string into a credential.
test("treats a blank write token as unset and stays in certificate mode", async () => {
  vi.stubEnv("N8N_MONITORING_WRITE_TOKEN", "   ");
  const app = await build();
  expect(app.config.writeToken).toBeUndefined();

  const res = await app.inject({
    method: "POST",
    url: URL,
    headers: { authorization: "Bearer " },
    payload: { instanceId: "x" },
  });
  expect(res.statusCode).toBe(401);
  expect(res.json()).toMatchObject({ message: "Missing license certificate" });
});

import { expect, test } from "vitest";
import { build } from "../../test-utils/build-app";
import { generateMockLicense } from "../../test-utils/mock-license";

// The compose file, the k8s demo and the backfill script all run in token
// mode, so outside this suite nothing exercises certificate mode against a
// listening server. This test does: a real socket, a real HTTP body of
// realistic size, no inject() shortcut, from request to stored row.
test("a license certificate authenticates a report over real HTTP", async () => {
  const app = await build();
  // Certificate mode: the harness sets no write token.
  expect(app.config.writeToken).toBeUndefined();
  const baseUrl = await app.listen({ port: 0, host: "127.0.0.1" });

  const report = {
    instanceId: "e2e-instance",
    batchId: "e2e-batch-1",
    n8nVersion: "1.99.0",
    dataPoints: [{ kind: "daily", name: "billableExecutions", value: 12, date: "2026-03-25" }],
    licenseCert: generateMockLicense(),
  };

  const res = await fetch(`${baseUrl}/api/v1/instance-reports`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(report),
  });
  expect(res.status).toBe(201);

  const { id } = (await res.json()) as { id: number };
  const [row] = (await app.dataSource.query("SELECT instanceId, batchId, data FROM instance_reports WHERE id = ?", [
    id,
  ])) as Record<string, string>[];
  expect(row.instanceId).toBe("e2e-instance");
  expect(row.batchId).toBe("e2e-batch-1");
  expect(JSON.parse(row.data)).toEqual(report.dataPoints);
  expect(JSON.stringify(row)).not.toContain(report.licenseCert);

  // Same report without any credential, to show the certificate did the work.
  const { licenseCert: _omitted, ...bare } = report;
  const unauthenticated = await fetch(`${baseUrl}/api/v1/instance-reports`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ ...bare, batchId: "e2e-batch-2" }),
  });
  expect(unauthenticated.status).toBe(401);
});

{{- $secret := required "auth.existingSecret is required: the name of a Secret holding the read token. The service refuses to start without it." .Values.auth.existingSecret }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "airgap-monitoring.fullname" . }}
  namespace: {{ .Release.Namespace }}
  labels:
    {{- include "airgap-monitoring.labels" . | nindent 4 }}
spec:
  # Exactly one replica, and not configurable: SQLite on a ReadWriteOnce volume
  # supports a single writer. Do not add an HPA or a second replica.
  replicas: 1
  revisionHistoryLimit: 3
  # Recreate, not RollingUpdate: a second pod could not mount the RWO volume
  # while the old one still holds it, so a rolling update would hang. The
  # cost is a few seconds of downtime per upgrade, during which reporting
  # instances retry.
  strategy:
    type: Recreate
  selector:
    matchLabels:
      {{- include "airgap-monitoring.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      labels:
        {{- include "airgap-monitoring.labels" . | nindent 8 }}
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
    spec:
      # The service never calls the Kubernetes API.
      automountServiceAccountToken: false
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.podSecurityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.priorityClassName }}
      priorityClassName: {{ . }}
      {{- end }}
      containers:
        - name: airgap-monitoring
          image: "{{ .Values.image.repository }}:{{ include "airgap-monitoring.imageTag" . }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          {{- with .Values.containerSecurityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          ports:
            # The image listens on 3000; the Service maps service.port onto it.
            - name: http
              containerPort: 3000
              protocol: TCP
          env:
            - name: N8N_DB_PATH
              value: /data/database.sqlite
            - name: N8N_MONITORING_READ_TOKEN
              valueFrom:
                secretKeyRef:
                  name: {{ $secret }}
                  key: {{ .Values.auth.readTokenKey }}
            # Optional. Present: instances must send it as a bearer token and
            # certificates are not accepted. Absent: certificate mode.
            - name: N8N_MONITORING_WRITE_TOKEN
              valueFrom:
                secretKeyRef:
                  name: {{ $secret }}
                  key: {{ .Values.auth.writeTokenKey }}
                  optional: true
            {{- with .Values.nodeOptions }}
            - name: NODE_OPTIONS
              value: {{ . | quote }}
            {{- end }}
            {{- with .Values.extraEnv }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
          # /healthz answers as soon as the HTTP server is up. Startup is
          # generous because schema migrations run before the port opens and
          # may take a while on a database holding years of reports.
          startupProbe:
            httpGet:
              path: /healthz
              port: http
            periodSeconds: 5
            failureThreshold: 60
          readinessProbe:
            httpGet:
              path: /healthz
              port: http
            periodSeconds: 10
            timeoutSeconds: 3
          livenessProbe:
            httpGet:
              path: /healthz
              port: http
            periodSeconds: 20
            timeoutSeconds: 3
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
          volumeMounts:
            - name: data
              mountPath: /data
            # SQLite writes temporary files for large sorts; with a read-only
            # root filesystem it needs a writable /tmp.
            - name: tmp
              mountPath: /tmp
      volumes:
        - name: data
          persistentVolumeClaim:
            claimName: {{ include "airgap-monitoring.claimName" . }}
        - name: tmp
          emptyDir: {}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}

import { timingSafeEqual, X509Certificate } from "node:crypto";
import type { FastifyInstance, FastifyReply, FastifyRequest } from "fastify";
import fp from "fastify-plugin";
import { N8N_LICENSE_ISSUER_CERT_PEM } from "../license/issuer-cert";
import { LicenseCertError, verifyLicenseCert } from "../license/license-cert";

/** Name of the body field carrying the certificate. Stripped before the body goes anywhere else. */
export const LICENSE_CERT_FIELD = "licenseCert";

type Verifier = (request: FastifyRequest) => void;

/**
 * Authenticates a reporting n8n instance. The operator picks one of two modes
 * by whether `N8N_MONITORING_WRITE_TOKEN` is set; the choice is made once at
 * start-up and there is no mode that accepts both:
 *
 * - Token mode (variable set): the request must carry the token verbatim as
 *   `Authorization: Bearer <token>`. Certificates are not looked at, so only
 *   holders of the operator's secret can write, and the endpoint needs no
 *   network restriction beyond TLS.
 * - Certificate mode (variable unset): the request must carry the instance's
 *   n8n license certificate as `licenseCert` in the body. Possession of a
 *   certificate n8n issued is the whole check: no identity is read from it and
 *   nothing is stored. Any licensee's certificate passes, so the endpoint must
 *   be reachable only by the operator's own instances.
 *
 * The certificate travels in the body, not a header, because a real one is
 * about 7 KB and grows with every feature flag, which sits too close to the
 * 8 KB per-header default of common reverse proxies.
 *
 * Trust for certificates is the embedded n8n license CA. Tests replace it with
 * a mock CA via `TEST_LICENSE_ISSUER_CERT`, honoured only under
 * `NODE_ENV=test`, the same mechanism ai-assistant-service uses. The
 * production image bakes `NODE_ENV=production`, so the variable is inert on a
 * deployed container.
 */
export default fp(
  async (fastify: FastifyInstance) => {
    const { writeToken } = fastify.config;
    const verify: Verifier = writeToken !== undefined ? bearerVerifier(writeToken) : certificateVerifier();

    /**
     * Runs as `preValidation`, so the body is parsed but the route schema has
     * not seen it yet: a bad credential gets 401 before a malformed report gets
     * 400, and an unauthenticated caller learns nothing about the schema.
     */
    async function authenticateReport(request: FastifyRequest, _reply: FastifyReply): Promise<void> {
      verify(request);

      // The service persists the whole report object, so a certificate must
      // not still be in it, in either mode. The route schema would strip it
      // too, but a second write path must not depend on that.
      if (isRecord(request.body)) {
        delete request.body[LICENSE_CERT_FIELD];
      }
    }

    function bearerVerifier(expected: string): Verifier {
      return (request) => {
        const presented = bearerTokenOf(request);
        if (presented === undefined) {
          throw fastify.httpErrors.unauthorized("Missing write token");
        }
        if (!tokensEqual(presented, expected)) {
          // The presented value is never logged.
          request.log.warn({ code: "BAD_TOKEN" }, "Rejected write token");
          throw fastify.httpErrors.unauthorized("Invalid write token");
        }
      };
    }

    function certificateVerifier(): Verifier {
      const testCert = process.env.NODE_ENV === "test" ? process.env.TEST_LICENSE_ISSUER_CERT : undefined;
      const issuer = new X509Certificate(testCert || N8N_LICENSE_ISSUER_CERT_PEM);

      return (request) => {
        const body: unknown = request.body;
        if (!isRecord(body)) {
          throw fastify.httpErrors.unauthorized("Missing license certificate");
        }

        const cert = body[LICENSE_CERT_FIELD];
        if (typeof cert !== "string" || cert.length === 0) {
          throw fastify.httpErrors.unauthorized("Missing license certificate");
        }

        try {
          verifyLicenseCert(cert, issuer);
        } catch (error) {
          if (error instanceof LicenseCertError) {
            // The code is the only thing about the certificate that may be logged.
            request.log.warn({ code: error.code }, "Rejected license certificate");
            throw fastify.httpErrors.unauthorized("Invalid license certificate");
          }
          throw error;
        }
      };
    }

    fastify.decorate("authenticateReport", authenticateReport);
  },
  { name: "reportAuth", dependencies: ["config", "sensible"] },
);

/** The value after `Bearer `, or undefined when the header is absent or uses another scheme. */
function bearerTokenOf(request: FastifyRequest): string | undefined {
  const header = request.headers.authorization;
  if (typeof header !== "string") return undefined;
  const match = /^Bearer\s+(.+)$/i.exec(header.trim());
  return match?.[1];
}

/** Constant-time comparison, so response timing reveals nothing about the token. */
function tokensEqual(presented: string, expected: string): boolean {
  const a = Buffer.from(presented);
  const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

declare module "fastify" {
  export interface FastifyInstance {
    authenticateReport: (request: FastifyRequest, reply: FastifyReply) => Promise<void>;
  }
}

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expect, test } from "vitest";
import { airgapMonitoringVersion } from "./version";

test("matches the release version in the root package.json", () => {
  const root = JSON.parse(readFileSync(join(__dirname, "../../../package.json"), "utf8"));

  expect(airgapMonitoringVersion).toBe(root.version);
