// This file contains code that we reuse between our tests.
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import Fastify from "fastify";
import fp from "fastify-plugin";
import { onTestFinished } from "vitest";
import app from "../app";
import { TEST_ISSUER_CERT_PEM } from "./mock-license";

process.env.N8N_MONITORING_READ_TOKEN = "[REDACTED]";
// Certificate mode by default: no write token, and the test CA is trusted once
// here, so every test mints certificates through mock-license.ts and nothing
// else. Tests of token mode stub N8N_MONITORING_WRITE_TOKEN before build().
// The auth plugin honours TEST_LICENSE_ISSUER_CERT only under NODE_ENV=test,
// which the Vitest config pins.
delete process.env.N8N_MONITORING_WRITE_TOKEN;
process.env.TEST_LICENSE_ISSUER_CERT = TEST_ISSUER_CERT_PEM;

// Automatically build and tear down our instance
async function build() {
  // Every test gets its own throwaway database file, so no test can observe
  // another test's events.
  const dataDir = mkdtempSync(join(tmpdir(), "airgap-monitoring-test-"));
  process.env.N8N_DB_PATH = join(dataDir, "database.sqlite");

  // The real app on a bare Fastify instance, wrapped in fastify-plugin only so its decorators are reachable from tests.
  const fastify = Fastify();
  await fastify.register(fp(app));
  await fastify.ready();

  onTestFinished(async () => {
    await fastify.close();
    rmSync(dataDir, { recursive: true, force: true });
  });

  return fastify;
}

export { build };

import Fastify from "fastify";
import fp from "fastify-plugin";
import { expect, onTestFinished, test } from "vitest";
import app from "../app";
import { build } from "../test-utils/build-app";

test("opens the database in WAL mode with synchronous left at FULL", async () => {
  const { dataSource } = await build();

  expect(await dataSource.query("PRAGMA journal_mode")).toEqual([{ journal_mode: "wal" }]);
  // 2 is FULL. See https://www.sqlite.org/pragma.html#pragma_synchronous
  expect(await dataSource.query("PRAGMA synchronous")).toEqual([{ synchronous: 2 }]);
});

test("runs migrations on startup and records them once", async () => {
  const { dataSource } = await build();

  const applied = await dataSource.query("SELECT name FROM migrations ORDER BY id");

  expect(applied).toEqual([{ name: "CreateInstanceReports1788912000000" }]);
});

// Every container restart is a second start against a populated file. The
// baseline migration is not idempotent on purpose, so this proves the
// bookkeeping keeps it from running twice.
test("a second start against the same database file keeps its data and does not re-run migrations", async () => {
  const first = await build();
  await first.dataSource.query(
    `INSERT INTO instance_reports (instanceId, batchId, n8nVersion, data, receivedAt)
     VALUES ('instance-1', 'batch-1', '1.99.0', '[]', '2026-03-25T00:00:00.000Z')`,
  );

  // build() left N8N_DB_PATH pointing at the first instance's file.
  const second = Fastify();
  await second.register(fp(app));
  await second.ready();
  onTestFinished(async () => {
    await second.close();
  });

  expect(await second.dataSource.query("SELECT COUNT(*) AS count FROM migrations")).toEqual([{ count: 1 }]);
  expect(await second.dataSource.query("SELECT batchId FROM instance_reports")).toEqual([{ batchId: "batch-1" }]);
});

// Ported from ai-assistant-service's mockLicenseGenerator: mints license
// certificate containers in the exact format the license server produces,
// signed by a throwaway CA generated when this module loads.
//
// The receiver checks none of the payload's contents, so the payload is kept
// to the minimum a real certificate carries. Dates are accepted regardless of
// value, which the `expired` option exists to prove.
import { randomBytes } from "node:crypto";
import CryptoJS from "crypto-js";
import forge from "node-forge";
import NodeRSA from "node-rsa";

export interface MockCa {
  privateKeyPem: string;
  certPem: string;
}

export interface MockLicenseOptions {
  /** Signs with a different CA than the module default. */
  ca?: MockCa;
  /** Puts expiresAt and terminatesAt in the past. */
  expired?: boolean;
  consumerRef?: string;
  isEphemeral?: boolean;
}

const DAY_MS = 24 * 60 * 60 * 1000;

/** A self-signed certificate acting as both CA and leaf, like the ai-assistant-service mock. */
export function generateMockCa(commonName = "test.license.n8n.io"): MockCa {
  const keyPair = forge.pki.rsa.generateKeyPair(2048);
  const cert = forge.pki.createCertificate();

  cert.publicKey = keyPair.publicKey;
  cert.serialNumber = randomBytes(8).toString("hex");
  cert.validity.notBefore = new Date();
  cert.validity.notAfter = new Date();
  cert.validity.notAfter.setFullYear(cert.validity.notBefore.getFullYear() + 10);

  const attrs = [
    { name: "commonName", value: commonName },
    { name: "countryName", value: "DE" },
    { shortName: "ST", value: "Berlin" },
    { name: "localityName", value: "Berlin" },
  ];
  cert.setSubject(attrs);
  cert.setIssuer(attrs);
  cert.setExtensions([
    { name: "basicConstraints", cA: true },
    { name: "keyUsage", keyCertSign: true, digitalSignature: true, nonRepudiation: true },
  ]);
  cert.sign(keyPair.privateKey, forge.md.sha256.create());

  return {
    privateKeyPem: forge.pki.privateKeyToPem(keyPair.privateKey),
    certPem: forge.pki.certificateToPem(cert),
  };
}

/** The CA every test trusts by default. Generated once per process. */
export const TEST_CA: MockCa = generateMockCa();

/** Trust this on the receiver to accept certificates from {@link generateMockLicense}. */
export const TEST_ISSUER_CERT_PEM = TEST_CA.certPem;

/**
 * A base64 license certificate container, as n8n would read from
 * `N8N_LICENSE_CERT` and send as `licenseCert`.
 */
export function generateMockLicense(options: MockLicenseOptions = {}): string {
  const { ca = TEST_CA, expired = false, consumerRef = "test@airgap.dev", isEphemeral = true } = options;

  const now = Date.now();
  const validTo = new Date(now + (expired ? -1 : 365) * DAY_MS);

  const payload = JSON.stringify({
    consumerId: "00000000-0000-0000-0000-000000000000",
    consumerRef,
    version: 2,
    tenantId: 1,
    renewalToken: "",
    deviceLock: false,
    deviceFingerprint: "",
    createdAt: new Date(now - DAY_MS).toISOString(),
    issuedAt: new Date(now - DAY_MS).toISOString(),
    expiresAt: validTo.toISOString(),
    terminatesAt: validTo.toISOString(),
    managementJwt: "",
    isEphemeral,
    detachedEntitlementsCount: 0,
    entitlements: [
      {
        id: "test-entitlement-id",
        productId: "00000000-0000-0000-0000-000000000000",
        productMetadata: {},
        features: { "feat:sharing": true, "quota:users": -1 },
        featureOverrides: {},
        validFrom: new Date(now - DAY_MS).toISOString(),
        validTo: validTo.toISOString(),
        isFloatable: false,
      },
    ],
  });

  return buildContainer(payload, ca);
}

/**
 * Assembles the container from a payload string and the CA that signs it.
 * Exposed so a test can sign one payload and then tamper with it.
 */
export function buildContainer(payload: string, ca: MockCa = TEST_CA): string {
  const key = new NodeRSA(ca.privateKeyPem, "pkcs1-private-pem", { signingScheme: "pkcs1" });

  const symmetricKey = randomBytes(32).toString("hex");
  const encryptedData = CryptoJS.AES.encrypt(payload, symmetricKey).toString();
  const encryptedSymmetricKey = key.encryptPrivate(symmetricKey, "base64");
  const signature = key.sign(Buffer.from(payload), "base64", "utf8");

  const licenseKey = `-----BEGIN LICENSE KEY-----${encryptedSymmetricKey}||${encryptedData}||${signature}-----END LICENSE KEY-----`;

  return Buffer.from(JSON.stringify({ licenseKey, x509: ca.certPem })).toString("base64");
}

/** Well-formed and correctly signed, but by a CA the receiver does not trust. */
export function generateMockLicenseWithForgedIssuer(): string {
  return generateMockLicense({ ca: generateMockCa("forged.example") });
}

/**
 * Signed by the trusted CA, then re-encrypted with the payload altered, so the
 * chain and key recovery pass and only the signature check can catch it.
 */
export function generateMockLicenseWithTamperedPayload(): string {
  const genuine = decodeContainer(generateMockLicense());
  const match = genuine.licenseKey.match(
    /^(-----BEGIN LICENSE KEY-----)(.+)\|\|(.+)\|\|(.+)(-----END LICENSE KEY-----)$/,
  );
  if (!match) throw new Error("mock license key did not match its own format");

  const [, head, encryptedSymmetricKey, , signature, tail] = match;
  const key = new NodeRSA(TEST_CA.privateKeyPem, "pkcs1-private-pem", { signingScheme: "pkcs1" });
  const symmetricKey = key.decryptPublic(encryptedSymmetricKey, "utf8");
  const tampered = CryptoJS.AES.encrypt(JSON.stringify({ consumerId: "someone-else" }), symmetricKey).toString();

  return Buffer.from(
    JSON.stringify({
      licenseKey: `${head}${encryptedSymmetricKey}||${tampered}||${signature}${tail}`,
      x509: genuine.x509,
    }),
  ).toString("base64");
}

function decodeContainer(containerStr: string): { licenseKey: string; x509: string } {
  return JSON.parse(Buffer.from(containerStr, "base64").toString("ascii"));
}

import { expect, test } from "vitest";
import { LABEL_MAX_LENGTH, sanitizeLabel } from "./label";

test.each([
  ["kiwi-prod", "kiwi-prod"],
  ["Kiwi prod", "kiwi-prod"],
  ["Acme Prod / EU", "acme-prod-eu"],
  ["prod_eu.west", "prod-eu-west"],
  ["v2.40.6 (beta)", "v2-40-6-beta"],
  ["a   b___c", "a-b-c"],
  ["  --main--  ", "main"],
  ["Café Zürich", "cafe-zurich"],
  ["ﬁnance", "finance"],
  ["🚀 launch", "launch"],
  // No accent-free form, so the letter is dropped. Accepted for a display name.
  ["Straße", "stra-e"],
])("sanitizes %j to %j", (raw, expected) => {
  expect(sanitizeLabel(raw)).toBe(expected);
});

test.each(["!!!", "---"])("returns undefined when nothing of %j is left", (raw) => {
  expect(sanitizeLabel(raw)).toBeUndefined();
});

test("keeps a label at the maximum length", () => {
  const raw = "x".repeat(LABEL_MAX_LENGTH);

  expect(sanitizeLabel(raw)).toBe(raw);
});

test("cuts a longer label without leaving a trailing hyphen", () => {
  // The cut falls right after the hyphen that replaced the space.
  const label = sanitizeLabel(`${"x".repeat(LABEL_MAX_LENGTH - 1)} ${"y".repeat(500)}`);

