describe("streamInstanceReports filtered by start and end", () => {
  const daily = (date: string) => ({ kind: "daily" as const, name: "billableExecutions", value: 1, date });

  const cumulative = (batchId: string, receivedAt: string) =>
    row({ batchId, receivedAt, dataPoints: [{ kind: "cumulative", name: "billableExecutions", value: 1 }] });

  test("when daily values fall on the start or end day, then they are kept, and a day outside is left out", async () => {
    const service = fakeReportService([
      row({ dataPoints: [daily("2026-09-30"), daily("2026-10-01"), daily("2026-10-31"), daily("2026-11-01")] }),
    ]);

    const [instance] = await collectInstances(service, { start: "2026-10-01", end: "2026-10-31" });

    expect(instance.dataPoints.billableExecutions.map((point) => (point.kind === "daily" ? point.date : ""))).toEqual([
      "2026-10-01",
      "2026-10-31",
    ]);
  });

  test("when a cumulative value is received on the start or end day, then it is kept, and a millisecond outside is left out", async () => {
    const service = fakeReportService([
      cumulative("before-start", "2026-09-30T23:59:59.999Z"),
      cumulative("on-start", "2026-10-01T00:00:00.000Z"),
      cumulative("on-end", "2026-10-31T23:59:59.999Z"),
      cumulative("after-end", "2026-11-01T00:00:00.000Z"),
    ]);

    const [instance] = await collectInstances(service, { start: "2026-10-01", end: "2026-10-31" });

    expect(instance.dataPoints.billableExecutions.map((point) => point.batchId)).toEqual(["on-start", "on-end"]);
  });

  test("when an instance has no values in the range, then it is left out of the report", async () => {
    const service = fakeReportService([
      row({ instanceId: "in-range", dataPoints: [daily("2026-10-15")] }),
      row({ instanceId: "out-of-range", dataPoints: [daily("2026-11-15")] }),
    ]);

    const instances = await collectInstances(service, { start: "2026-10-01", end: "2026-10-31" });

    expect(instances.map((i) => i.instanceId)).toEqual(["in-range"]);
  });

  test("when the range excludes some rows, then firstSeen, lastReportAt and label still come from the full history", async () => {
    const service = fakeReportService([
      row({ batchId: "b1", label: "first", receivedAt: "2026-09-01T02:00:00.000Z", dataPoints: [daily("2026-08-31")] }),
      row({
        batchId: "b2",
        label: "middle",
        receivedAt: "2026-10-16T02:00:00.000Z",
        dataPoints: [daily("2026-10-15")],
      }),
      row({
        batchId: "b3",
        label: "latest",
        receivedAt: "2026-12-01T02:00:00.000Z",
        dataPoints: [daily("2026-11-30")],
      }),
    ]);

    const [instance] = await collectInstances(service, { start: "2026-10-01", end: "2026-10-31" });

    expect(instance).toMatchObject({
      firstSeen: "2026-09-01T02:00:00.000Z",
      lastReportAt: "2026-12-01T02:00:00.000Z",
      label: "latest",
    });
  });
});

// Development CLI. Prints a complete, schema-valid POST body for
// /api/v1/instance-reports, so a report can be posted without an n8n instance.
// Authenticate the request with the write token:
//
//   pnpm --filter api --silent mock-report --label demo --days 3 | \
//     curl -sS -X POST localhost:3001/api/v1/instance-reports \
//       -H 'authorization: Bearer dev-write-token' -H 'content-type: application/json' -d @-
//
// Or set N8N_LICENSE_CERT to a real n8n license certificate and the body
// carries it as `licenseCert` instead, for a receiver without a write token.
import { randomBytes, randomUUID } from "node:crypto";
import { parseArgs } from "node:util";

const USAGE = `usage: mock-report [--instance-id ID] [--label LABEL] [--days N]
  --label LABEL  stored sanitized and cut to 200 characters
  --days N       add N daily data points ending yesterday (default 0)
  N8N_LICENSE_CERT, when set, is embedded as licenseCert`;

const DAY_MS = 24 * 60 * 60 * 1000;

function fail(message: string): never {
  process.stderr.write(`${message}\n`);
  process.exit(2);
}

const { values } = parseArgs({
  options: {
    "instance-id": { type: "string" },
    label: { type: "string" },
    days: { type: "string", default: "0" },
    help: { type: "boolean", short: "h", default: false },
  },
});

if (values.help) {
  process.stdout.write(`${USAGE}\n`);
  process.exit(0);
}

const days = Number(values.days);
if (!Number.isInteger(days) || days < 0) fail(`--days must be a non-negative integer\n${USAGE}`);

const yesterday = Date.now() - DAY_MS;
const dailyPoints = Array.from({ length: days }, (_, offset) => ({
  kind: "daily",
  name: "billableExecutions",
  value: 1000 + Math.floor(Math.random() * 1000),
  date: new Date(yesterday - offset * DAY_MS).toISOString().slice(0, 10),
})).reverse();

const licenseCert = process.env.N8N_LICENSE_CERT;

const report = {
  // n8n derives its id as a sha256 hex digest; match the shape.
  instanceId: values["instance-id"] ?? randomBytes(32).toString("hex"),
  batchId: randomUUID(),
  ...(values.label ? { label: values.label } : {}),
  n8nVersion: "0.0.0-mock",
  dataPoints: [{ kind: "cumulative", name: "billableExecutions", value: 10_000 + days * 1500 }, ...dailyPoints],
  ...(licenseCert ? { licenseCert } : {}),
};

process.stdout.write(`${JSON.stringify(report)}\n`);

